mapper.select:
select wso.*, p.id pid, p.short_name psName, p.serial_number pSN, p.name pn, pm.name pmName, pa.name paName, mbf.id mbfId, mbf.name mbfName, obf.id obfId, obf.name obfName, wm.measure_unit wmu, wm.measure_precision wmp, wm.accounting_unit wau, wm.accounting_precision wap, wc.name classifyName, ww.id wwId, ww.name wwName from wms_statistics_outbound wso left join contract_project p on p.id = wso.project_id left join wms_measure wm on wm.classification_id = wso.classify_id left join wms_workshop mbf on wso.workshop_id = mbf.id left join wms_move_outbound_detail `mod` on `mod`.id = wso.detail_id and wso.receipt_type = 14 left join wms_return_detail rd on rd.id = wso.detail_id and wso.receipt_type = 16 left join wms_material_returnable mr2 on mr2.id = rd.material_returnable_id left join mes_building_workshop obf on obf.id = CASE WHEN wso.receipt_type = 14 THEN `mod`.workshop_id ELSE mr2.workshop_id END left join wms_warehouse ww on ww.id = wso.warehouse_id left join wms_classification wc on wso.classify_id = wc.id left join plan_monomer pm on pm.id = wso.monomer_id left join plan_area pa on pa.id = wso.area_id where wso.bool_delete_enum = 0
and outbound_time > #{times.startTime}
and outbound_time < #{times.endTime}
and wso.statistics_id in
#{item}

select wso.*, p.id pid, p.short_name psName, p.serial_number pSN, p.name pn, pm.name pmName, pa.name paName, mbf.id mbfId, mbf.name mbfName, obf.id obfId, obf.name obfName, wm.measure_unit wmu, wm.measure_precision wmp, wm.accounting_unit wau, wm.accounting_precision wap, wc.name classifyName, ww.id wwId, ww.name wwName from wms_statistics_outbound wso left join contract_project p on p.id = wso.project_id left join wms_measure wm on wm.classification_id = wso.classify_id left join wms_workshop mbf on wso.workshop_id = mbf.id left join wms_move_outbound_detail `mod` on `mod`.id = wso.detail_id and wso.receipt_type = 14 left join wms_return_detail rd on rd.id = wso.detail_id and wso.receipt_type = 16 left join wms_material_returnable mr2 on mr2.id = rd.material_returnable_id left join mes_building_workshop obf on obf.id = CASE WHEN wso.receipt_type = 14 THEN `mod`.workshop_id ELSE mr2.workshop_id END left join wms_warehouse ww on ww.id = wso.warehouse_id left join wms_classification wc on wso.classify_id = wc.id left join plan_monomer pm on pm.id = wso.monomer_id left join plan_area pa on pa.id = wso.area_id where wso.bool_delete_enum = 0 and wso.create_time > #{times.startTime} and wso.create_time < #{times.endTime}
and wso.statistics_id in
#{item}

select *
from  wms_statistics_outbound
where
DATE_FORMAT(NOW(), '%Y%m') = DATE_FORMAT(create_time, '%Y%m')
and statistics_id = #{id}
and bool_delete_enum = 0
and basic_class = #{mat.basicClass}
and classify_id = #{mat.classifyId}
and bool_party_a = #{mat.boolPartyA}

    AND tax_rate = #{mat.taxRate}


    AND tax_rate is null


    and workshop_id = #{mat.workshopId}


    AND warehouse_id = #{mat.warehouseId}


    AND specification = #{mat.specification}


    AND specification is null


    AND length = #{mat.length}


    AND length is null


    AND width = #{mat.width}


    AND width is null


    AND thickness = #{mat.thickness}


    AND thickness is null


    AND unit_net = #{mat.unitNet}


    AND unit_net is null


    AND project_id = #{mat.projectId}


    AND project_id is null


    AND heat_no_and_batch_no = #{mat.heatNoAndBatchNo}


    AND heat_no_and_batch_no is null


    AND brand = #{mat.brand}


    AND brand is null


    AND color = #{mat.color}


    AND color is null

select SUM(amount_excluding_vat)
from wms_statistics_outbound
where bool_delete_enum = 0

    and outbound_time > #{times.startTime}


    and outbound_time < #{times.endTime}

select IFNULL(SUM(amount_excluding_vat),0)
from wms_statistics_outbound
where bool_delete_enum = 0
  and create_time > #{times.startTime}
  and create_time < #{times.endTime}

    and basic_class & #{basicClass} > 0


    and workshop_id = #{workshopId}

        select IFNULL(SUM(mete),0)
        from wms_statistics_outbound
        where bool_delete_enum = 0
        and create_time > #{times.startTime}
        and create_time < #{times.endTime}
        
            and basic_class & #{basicClass} > 0
        
        
            and workshop_id = #{workshopId}
